solution.solution.cpp:
#include <bitset>
#include <cstdint>
#include <optional>

int sequenceDifference(std::uint16_t a, std::uint16_t b)
{
    return static_cast<std::int16_t>(static_cast<std::uint16_t>(a - b));
}

bool sequenceGreater(std::uint16_t a, std::uint16_t b)
{
    return sequenceDifference(a, b) > 0;
}

class DuplicateFilter
{
public:
    bool accept(std::uint16_t sequence)
    {
        if (!latest_)
        {
            latest_ = sequence;
            seen_.set(sequence % 256);
            return true;
        }
        const int d{ sequenceDifference(sequence, *latest_) };
        if (d > 0)
        {
            if (d >= 256) seen_.reset();
            else
                for (int i{ 1 }; i <= d; ++i) seen_.reset(static_cast<std::uint16_t>(*latest_ + i) % 256);
            latest_ = sequence;
            seen_.set(sequence % 256);
            return true;
        }
        if (d == 0 || -d >= 256 || seen_.test(sequence % 256)) return false;
        seen_.set(sequence % 256);
        return true;
    }

    std::optional<std::uint16_t> latest() const { return latest_; }

private:
    std::optional<std::uint16_t> latest_;
    std::bitset<256> seen_;
};

unitTests:
TEST("differences across the wrap") {
    CHECK_EQ(sequenceDifference(5, 3), 2);
    CHECK_EQ(sequenceDifference(3, 5), -2);
    CHECK_EQ(sequenceDifference(2, 65534), 4);
    CHECK_EQ(sequenceDifference(65534, 2), -4);
    CHECK_EQ(sequenceDifference(32767, 0), 32767);
    CHECK_EQ(sequenceDifference(0, 32768), -32768);
    CHECK_EQ(sequenceDifference(7, 7), 0);
}
TEST("newer or not") {
    CHECK(sequenceGreater(5, 3));
    CHECK(!sequenceGreater(3, 5));
    CHECK(sequenceGreater(2, 65534));
    CHECK(!sequenceGreater(65534, 2));
    CHECK(sequenceGreater(0, 65535));
    CHECK(!sequenceGreater(9, 9));
    CHECK(sequenceGreater(32767, 0));
    CHECK(!sequenceGreater(32768, 0));
    CHECK(!sequenceGreater(0, 32768));
}
TEST("duplicates and late packets") {
    DuplicateFilter f;
    CHECK(!f.latest().has_value());
    CHECK(f.accept(10));
    CHECK(!f.accept(10));
    CHECK(f.accept(12));
    CHECK(f.accept(11));
    CHECK(!f.accept(11));
    CHECK(!f.accept(12));
    CHECK(f.latest() == std::optional<std::uint16_t>{ 12 });
}
TEST("across the wrap") {
    DuplicateFilter f;
    CHECK(f.accept(65530));
    CHECK(f.accept(65535));
    CHECK(f.accept(3));
    CHECK(!f.accept(65535));
    CHECK(f.accept(65533));
    CHECK(f.latest() == std::optional<std::uint16_t>{ 3 });
}
TEST("the window edge") {
    DuplicateFilter f;
    CHECK(f.accept(1000));
    CHECK(!f.accept(744));
    CHECK(f.accept(745));
    CHECK(f.accept(2000));
    CHECK(!f.accept(1000));
    CHECK(f.accept(1999));
}
TEST("old marks are cleared as the window slides") {
    DuplicateFilter f;
    CHECK(f.accept(0));
    CHECK(f.accept(1));
    CHECK(f.accept(2));
    CHECK(f.accept(257));
    CHECK(f.accept(256));
    CHECK(!f.accept(2));
    DuplicateFilter g;
    CHECK(g.accept(100));
    CHECK(g.accept(101));
    CHECK(g.accept(357));
    CHECK(g.accept(356));
}

